index 78255e2f8..7221f2815 100644
--- a/plugins/org.jkiss.dbeaver.model/src/org/jkiss/dbeaver/model/DBUtils.java
+++ b/plugins/org.jkiss.dbeaver.model/src/org/jkiss/dbeaver/model/DBUtils.java
@@ -136,11 +136,7 @@ public final class DBUtils {
      */
     @NotNull
     public static String getQuotedIdentifier(@NotNull DBSObject object) {
-        if (object instanceof DBSContextBoundAttribute cba) {
-            return cba.formatMemberReference(false, null, DBPAttributeReferencePurpose.UNSPECIFIED);
-        } else {
-            return getQuotedIdentifier(object.getDataSource(), object.getName());
-        }
+        return getQuotedIdentifier(object, DBPAttributeReferencePurpose.UNSPECIFIED);
     }

     /**
diff --git a/plugins/org.jkiss.dbeaver.model/src/org/jkiss/dbeaver/model/impl/admin/locks/LockGraphManager.java b/plugins/org.jkiss.dbeaver.model/src/org/jkiss/dbeaver/model/impl/admin/locks/LockGraphManager.java
index 196071185..e305fd3c0 100644
--- a/plugins/org.jkiss.dbeaver.model/src/org/jkiss/dbeaver/model/impl/admin/locks/LockGraphManager.java
+++ b/plugins/org.jkiss.dbeaver.model/src/org/jkiss/dbeaver/model/impl/admin/locks/LockGraphManager.java
@@ -27,8 +27,8 @@ public abstract class LockGraphManager {
     public static final String typeWait = "wait";
     public static final String typeHold = "hold";

-    private Map<Object, LockGraphNode> nodes = new HashMap<>();
-    private Map<Object, LockGraph> graphIndex = new HashMap<>();
+    private final Map<Object, LockGraphNode> nodes = new HashMap<>();
+    private final Map<Object, LockGraph> graphIndex = new HashMap<>();

     public LockGraph getGraph(DBAServerLock curLock) {

@@ -65,7 +65,7 @@ public abstract class LockGraphManager {

         Map<Object, DBAServerLock> childs = new HashMap<>();

-        while (current.size() > 0) {
+        while (!current.isEmpty()) {
             if (maxWidth < current.size()) {
                 maxWidth = current.size();
             }
@@ -84,39 +84,23 @@ public abstract class LockGraphManager {

                 node.setSpan(current.size());

-
                 for (DBAServerLock c : l.waitThis()) {
-
                     if (touched.contains(c)) continue;
-
                     touched.add(c);
-
                     childs.put(c.getId(), c);
-
                     graphIndex.put(c.getId(), graph);
-
                     LockGraphNode nodeChild = nodes.get(c.getId());
-
                     graph.getNodes().add(nodeChild);
-
                     nodeChild.setLevel(level);
-
                     LockGraphEdge edge = new LockGraphEdge();
                     edge.setSource(node);
                     edge.setTarget(nodeChild);
-
                 }
-
-
             }

             level++;
-
             current = new ArrayList<>(childs.values());
-
             childs.clear();
-
-
         }

         graph.setMaxWidth(maxWidth);
@@ -125,32 +109,22 @@ public abstract class LockGraphManager {

     @SuppressWarnings({"unchecked", "rawtypes"})
     public void buildGraphs(Map<Object, ? extends DBAServerLock> locks) {
-
         Set<DBAServerLock> roots = new HashSet<>();
-
         this.nodes.clear();
-
         this.graphIndex.clear();
-
         for (DBAServerLock l : locks.values()) {
-
             if (locks.containsKey(l.getHoldID()) && (!l.getHoldID().equals(l.getId()))) {
-
                 DBAServerLock holder = locks.get(l.getHoldID());
                 l.setHoldBy(holder);
                 holder.waitThis().add(l);
-
             } else {
                 roots.add(l);
             }
-
             nodes.put(l.getId(), new LockGraphNode(l));
         }
-
         for (DBAServerLock root : roots) {
             createGraph(root);
         }
-
     }

 }
